export function subtitleConvert(input,target='vtt') {
  const blocks=input.replace(/^\uFEFF/,'').replace(/\r/g,'').trim().split(/\n\s*\n/),cues=[];
  const stamp=(s,sep)=>{const p=s.split(/[.,:]/).map(Number);if(p.length===3)p.unshift(0);if(p.length!==4||p[1]>59||p[2]>59)throw Error('A subtitle timestamp is invalid.');return `${String(p[0]).padStart(2,'0')}:${String(p[1]).padStart(2,'0')}:${String(p[2]).padStart(2,'0')}${sep}${String(p[3]).padStart(3,'0')}`;};
  for(const block of blocks){const lines=block.split('\n');if(/^(WEBVTT|NOTE|STYLE|REGION)(\s|$)/.test(lines[0]))continue;const i=lines.findIndex(l=>l.includes('-->'));if(i<0)continue;const m=lines[i].match(/^\s*((?:\d{2,}:)?\d{2}:\d{2}[.,]\d{3})\s*-->\s*((?:\d{2,}:)?\d{2}:\d{2}[.,]\d{3})(.*)$/);if(!m)throw Error('Use valid SRT or WebVTT timing lines.');const sep=target==='vtt'?'.':',';const timing=`${stamp(m[1],sep)} --> ${stamp(m[2],sep)}${target==='vtt'?m[3]:''}`,body=lines.slice(i+1).join('\n');if(body.trim())cues.push({timing,body});}
  if(!cues.length)throw Error('No subtitle cues found. Paste SRT or WebVTT content.');
  return{count:cues.length,text:(target==='vtt'?'WEBVTT\n\n':'')+cues.map((c,i)=>`${target==='srt'?i+1+'\n':''}${c.timing}\n${c.body}`).join('\n\n')+'\n'};
}
export function jsonCSV(input,delimiter=',',safe=true){const rows=typeof input==='string'?JSON.parse(input):input;if(!Array.isArray(rows)||!rows.length||!rows.every(r=>r&&typeof r==='object'&&!Array.isArray(r)))throw Error('Enter a nonempty JSON array of objects.');if(rows.length>10000)throw Error('Convert up to 10,000 rows at a time.');const columns=[...new Set(rows.flatMap(Object.keys))];if(!columns.length)throw Error('Add at least one property to the objects.');const cell=v=>{let s=v==null?'':typeof v==='object'?JSON.stringify(v):String(v);if(safe&&typeof v==='string'&&/^[\s]*[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};return {columns,rows:rows.length,text:'\uFEFF'+[columns.map(cell).join(delimiter),...rows.map(r=>columns.map(c=>cell(r[c])).join(delimiter))].join('\r\n')};}
export function campaignURL(base,params){const u=new URL(base);if(!['http:','https:'].includes(u.protocol)||u.username||u.password)throw Error('Use an HTTP or HTTPS link without embedded login details.');for(const key of ['source','medium','campaign','term','content']){const value=params[key]?.trim();if(value)u.searchParams.set('utm_'+key,value);else u.searchParams.delete('utm_'+key);}return u.href;}
export function contrastRatio(a,b){const lum=hex=>{if(!/^#[\da-f]{6}$/i.test(hex))throw Error('Choose valid six-digit HEX colors.');const c=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(v=>v<=.04045?v/12.92:((v+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722;};const x=lum(a),y=lum(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05);}
export const socialSizes={square:[1080,1080,'Square post'],portrait:[1080,1350,'Portrait post · 4:5'],story:[1080,1920,'Story / vertical canvas · 9:16'],thumbnail:[1280,720,'YouTube thumbnail canvas · 16:9'],landscape:[1200,630,'Link preview canvas · 1.91:1'],linkedin:[1200,1200,'Square professional post']};
export function icoFromPNG(png,size){const head=new Uint8Array(22),d=new DataView(head.buffer);d.setUint16(2,1,true);d.setUint16(4,1,true);head[6]=head[7]=size===256?0:size;d.setUint16(10,1,true);d.setUint16(12,32,true);d.setUint32(14,png.byteLength,true);d.setUint32(18,22,true);return new Blob([head,png],{type:'image/x-icon'});}
